class Solution {
    int best;
    int n;
    unordered_set<string> seen;

    void dfs(const string& s, int start, int count) {
        if (start == n) {
            best = max(best, count);
            return;
        }
        if (count + (n - start) <= best) return;
        for (int end = start + 1; end <= n; end++) {
            string sub = s.substr(start, end - start);
            if (seen.find(sub) == seen.end()) {
                seen.insert(sub);
                dfs(s, end, count + 1);
                seen.erase(sub);
            }
        }
    }
public:
    int maxUniqueSplit(string s) {
        this->n = s.size();
        this->best = 0;
        seen.clear();
        dfs(s, 0, 0);
        return best;
    }
};
